from datetime import datetime
from app.models import db

QUESTION_CATEGORIES = [
    "Technical",
    "Project",
    "Behavioral",
    "Resume-based",
    "Job-description-specific"
]

DIFFICULTY_LEVELS = ["Easy", "Medium", "Hard"]


class InterviewQuestion(db.Model):
    """Interview question bank generated by Gemini AI."""
    __tablename__ = "interview_questions"

    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    application_id = db.Column(db.Integer, db.ForeignKey("applications.id", ondelete="SET NULL"), nullable=True)
    
    job_title = db.Column(db.String(150), nullable=False)
    category = db.Column(db.String(50), nullable=False, index=True)
    question = db.Column(db.Text, nullable=False)
    difficulty = db.Column(db.String(20), nullable=False, default="Medium")
    interviewer_rationale = db.Column(db.Text, nullable=True)
    
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

    def to_dict(self) -> dict:
        """Serialize interview question model to dictionary."""
        return {
            "id": self.id,
            "user_id": self.user_id,
            "application_id": self.application_id,
            "job_title": self.job_title,
            "category": self.category,
            "question": self.question,
            "difficulty": self.difficulty,
            "interviewer_rationale": self.interviewer_rationale,
            "created_at": self.created_at.isoformat() if self.created_at else None
        }

    def __repr__(self) -> str:
        return f"<InterviewQuestion id={self.id} category={self.category} job={self.job_title}>"
